{
 "summary": "Two statements are formalized. `standardQuantumParallelRepetition` says that every finite game with entangled value below 1 has repeated entangled values bounded by C·exp(−c n) for some c, C > 0. This is a faithful qualitative form of the quantum parallel repetition result. `distributionUniformExponential` is meant to be the quantitative Theorem 1.1, but it only requires the universal constant to satisfy c ≥ 0. With c = 0 the bound reads ω*(G^{⊗n}) ≤ 1, which is trivial, so the quantitative theorem is effectively not formalized.",
 "glossary": [
  {"decl": "Game", "line": 12, "plain": "Finite two-player one-round game: a probability weight µ(x,y) on X×Y and a Boolean predicate V(x,y,a,b).", "standard_concept": "nonlocal game G=(X,Y,A,B,µ,V)", "matches_standard": "yes", "note": ""},
  {"decl": "Game.repeat", "line": 23, "plain": "n-fold parallel repetition: product question distribution; the players win iff every coordinate is won.", "standard_concept": "G^{⊗n}", "matches_standard": "yes", "note": ""},
  {"decl": "DensityMatrix", "line": 50, "plain": "PSD complex matrix of trace 1.", "standard_concept": "density matrix", "matches_standard": "yes", "note": ""},
  {"decl": "POVM", "line": 55, "plain": "Family of PSD effects summing to the identity.", "standard_concept": "POVM", "matches_standard": "yes", "note": ""},
  {"decl": "Strategy", "line": 60, "plain": "Finite-dimensional tensor-product strategy: a shared state on Alice⊗Bob, plus a POVM per question for each player.", "standard_concept": "entangled strategy (finite-dim tensor model)", "matches_standard": "yes", "note": "Dimensions are finite but arbitrary; the sup over these is the standard ω*."},
  {"decl": "Strategy.winProbability", "line": 87, "plain": "Σ_{x,y} µ(x,y) Σ_{a,b} V(x,y,a,b)·Re tr(ρ (A^x_a ⊗ B^y_b)).", "standard_concept": "winning probability", "matches_standard": "yes", "note": ""},
  {"decl": "entangledValue", "line": 94, "plain": "sSup of winning probabilities over all finite-dimensional strategies.", "standard_concept": "ω*(G)", "matches_standard": "yes", "note": "If A or B is empty there are no strategies and the value is the junk value sSup ∅ = 0."},
  {"decl": "HasExponentialBound", "line": 102, "plain": "∃ c>0, C>0, ∀ n, v n ≤ C e^{−cn}.", "standard_concept": "exponential decay", "matches_standard": "yes", "note": "The extra constant C is harmless up to adjusting constants."},
  {"decl": "StandardQuantumParallelRepetition", "line": 108, "plain": "ω*(G) < 1 → ω*(G^{⊗n}) decays exponentially.", "standard_concept": "quantum parallel repetition conjecture", "matches_standard": "yes", "note": ""}
 ],
 "lean_claims": [
  {"theorem": "distributionUniformExponential", "line": 112, "plain": "There exists c ≥ 0 such that for every finite game G with A and B nonempty and ε = 1 − ω*(G) > 0, and every n ≥ 1: ω*(G^{⊗n}) ≤ exp(−c·ε^13/(ε + log(|A||B|))·n)."},
  {"theorem": "standardQuantumParallelRepetition", "line": 130, "plain": "For every finite game G, if ω*(G) < 1 then there exist c > 0 and C > 0 with ω*(G^{⊗n}) ≤ C e^{−cn} for all n ∈ ℕ."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "There exists a universal c_qs > 0 such that for every finite game G with nonempty answer alphabets and ε = 1 − ω*(G) > 0, ω*(G^{⊗n}) ≤ exp(−c_qs ε^13/(ε + log(|A||B|)) n) for all n ≥ 1."},
  {"ref": "Quantum Parallel Repetition Conjecture (answered affirmatively)", "plain": "For every finite game G with ω*(G) < 1 there is c_G > 0 with ω*(G^{⊗n}) ≤ exp(−c_G n) for all n ≥ 1."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1.1", "lean_theorem": "distributionUniformExponential", "relation": "lean_weaker", "why": "The constant is only required to be ≥ 0, so c = 0 gives the trivial bound ω* ≤ 1."},
  {"paper_ref": "Quantum Parallel Repetition Conjecture (answered affirmatively)", "lean_theorem": "standardQuantumParallelRepetition", "relation": "equivalent", "why": "Uses a C·e^{−cn} bound, which is equivalent to an e^{−c'n} bound for n ≥ 1 after adjusting constants (given values < 1)."}
 ],
 "flags": [
  {"id": "F1", "category": "quantifier", "severity": "high", "decl": "distributionUniformExponential", "line": 113, "paper_ref": "Theorem 1.1", "explanation": "The statement asks for ∃ c, 0 ≤ c rather than 0 < c. Taking c = 0, the right-hand side is exp(0) = 1. Every winning probability is ≤ 1, and sSup ∅ = 0, so ω*(G^{⊗n}) ≤ 1 always holds. The quantitative theorem therefore becomes vacuous.", "polarity": "lean weaker", "probe_idea": "Prove distributionUniformExponential by `refine ⟨0, le_rfl, ?_⟩` followed by showing entangledValue ≤ 1 (simp; Real.exp_zero)."},
  {"id": "F2", "category": "junk-value", "severity": "low", "decl": "entangledValue", "line": 96, "paper_ref": null, "explanation": "With an empty answer set no POVM or strategy exists, so ω* = sSup ∅ = 0. This only affects degenerate games; Theorem 1.1 assumes Nonempty, and in standardQuantumParallelRepetition the empty case is trivially true.", "polarity": "n/a", "probe_idea": "Prove BddAbove (Set.range winProbability), and that the range is Nonempty when A and B are nonempty."}
 ],
